import{_ as o,l as r,o as e,c as s,v as t,p as D,x as i,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"die-to-die 与 die-to-database","description":"","frontmatter":{"title":"die-to-die 与 die-to-database","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-inspection-d2d-d2db.md","filePath":"litho/mask-inspection-d2d-d2db.md","lastUpdated":1789023840000}'),h={name:"litho/mask-inspection-d2d-d2db.md"};function B(E,a,c,m,_,A){const d=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="die-to-die-与-die-to-database" tabindex="-1">die-to-die 与 die-to-database <a class="header-anchor" href="#die-to-die-与-die-to-database" aria-label="Permalink to &quot;die-to-die 与 die-to-database&quot;">​</a></h1><div class="epigraph"><p>Die-to-die 只能看见两颗之间的差；金标准在数据库时，才能抓住整版都错的系统图形。</p><footer>—— 对照掩模光学检验 D2D / D2DB 的产线通称</footer></div><p><a href="/litho/mask-develop-clean">上一课</a>交出清洗后的版。缺口是缺陷要被检出：亮场/暗场光学、与谁比。本课钉 die-to-die（D2D）与 die-to-database（D2DB）。检出之后怎么修，留给[下一课](/litho/mask-repair-ebeam）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>重复芯片阵列可以用相邻 die 相减（D2D）：随机颗粒、针孔、多余铬会在差分里冒出来。整版系统性的 fracturing 错、层映射错、剂量整场偏，D2D 看不见——两颗一样错。D2DB 把图像与 MDP 金标准比对，能抓系统误差，但对准、渲染与曲线边更吃计算，误报也更多。</p><p>缺口是<strong>比较算子</strong>，不是再买一台显微镜。把「检验通过」写成「与设计一致」，在只跑 D2D 时不成立。</p><h3 id="euv-与光化" tabindex="-1">EUV 与光化 <a class="header-anchor" href="#euv-与光化" aria-label="Permalink to &quot;EUV 与光化&quot;">​</a></h3><p>DUV 透射检验波长往往不是 193 nm；打印行为靠模型或后课 AIMS。EUV 多层缺陷更需要光化视角（空白片已有光化检验传统）。本课钉逻辑：非光化 D2DB 会漏相位/多层缺陷，也会把不打印的噪声当缺陷。</p><p><span class="marginnote">曲线掩模的金标准必须是曲边算法。用曼哈顿渲染去比 ILT 边，合法曲率会变成「缺陷风暴」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>产线常 D2D+D2DB 分层：大面积重复走 D2D 保产能，关键与非重复（标记、唯一 ID）走 D2DB。灵敏度与 nuisance 是一对：过灵则修复队列炸，过钝则漏杀手缺陷。分类规则要与打印阈值（后课 AIMS）对齐，而不是与像素差对齐。</p><p>数据：D2DB 的 database 必须声明是 OPC 后、MPC 后、哪一网格——与 <a href="/litho/mask-data-prep">MDP 校验和</a> 同一条链。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学检验是部分相干成像，分辨率低于写栅。缺陷传递函数对针孔、桥、半透明残留不同。差分阈值随局部对比变：密线区噪声高，阈值若全局固定会漏或误报。这与晶圆缺陷检测同构，尺度在掩模 4× 几何上。</p>',14)),(e(),D(p,null,{default:i(()=>[n(d,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E6%A3%80%E9%AA%8C%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20D2D%5B%22die-to-die%20%E5%B7%AE%E5%88%86%22%5D%0A%20%20IMG%20--%3E%20D2DB%5B%22die-to-database%22%5D%0A%20%20DB%5B%22MDP%20%E9%87%91%E6%A0%87%E5%87%86%22%5D%20--%3E%20D2DB%0A%20%20D2D%20--%3E%20RAND%5B%22%E9%9A%8F%E6%9C%BA%E7%BC%BA%E9%99%B7%22%5D%0A%20%20D2DB%20--%3E%20SYS%5B%22%E7%B3%BB%E7%BB%9F%20%2B%20%E9%9A%8F%E6%9C%BA%22%5D%0A%20%20SYS%20--%3E%20REP%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E4%BF%AE%E5%A4%8D%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>检验不替代扫描机上的颗粒（pellicle 后）。不编造某机台的 nm 灵敏度表。D2DB 通过 ≠ AIMS 打印合格。</p><p>后课默认：缺陷清单已按 D2D/D2DB 列出；下一课用电子束或纳米机械去修可修的那些。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>D2D 抓随机差；D2DB 才能抓整版系统错。</li><li>金标准必须与 MDP 版本一致；曲线要用曲边比对。</li><li>非光化检验会漏相位/多层打印缺陷。</li><li>出处：掩模检验 D2D/D2DB 产线通称；SPIE Photomask 检验论述。</li></ul>',5))])}const f=o(h,[["render",B]]);export{u as __pageData,f as default};
